python3.checker:
class Checker:
    def matrixReshape(self, mat, r, c, result):
        if not isinstance(result, list) or not result or not all(isinstance(row, list) for row in result):
            return False
        m = len(mat)
        n = len(mat[0])
        if m * n != r * c:
            expected = mat
        else:
            flat = []
            for row in mat:
                flat.extend(row)
            expected = []
            index = 0
            for _ in range(r):
                expected.append(flat[index:index + c])
                index += c
        return result == expected

